import numpy as np
import json

# Parse test input
lines = test_input_str.strip().split('\n')
rows, cols = 22, 21
grid = np.array([[int(x) for x in line.split()] for line in lines])

# NEW THEORY: 
# Markers (6) trigger [5,6,6] pattern at cols (c, c+1, c+2)
# BUT: if a column already has input marker at c+1 or c+2, that column gets 6 instead of being overwritten
# And if input has marker at the same column c, that becomes 5

# Actually, let me try: [5,6,6] but preserve existing 6s
output = np.ones((rows, cols), dtype=int)

for r in range(rows):
    markers = sorted([c for c in range(cols) if grid[r, c] == 6])

    if len(markers) < 2:
        # Single marker: pattern [5,6,6]
        for i, marker_col in enumerate([markers[0]]):
            for j in range(3):
                col = marker_col + j
                if 0 <= col < cols:
                    # Only set if NOT already a marker (6)
                    if not (r, col) in [(r, mc) for mc in markers]:
                        output[r, col] = [5, 6, 6][j]
    else:
        # Multiple markers: place [5,6,6] but preserve existing 6s
        for marker_col in markers:
            for j in range(3):
                col = marker_col + j
                if 0 <= col < cols:
                    if grid[r, col] != 6:  # Don't overwrite existing markers
                        output[r, col] = [5, 6, 6][j]

